export async function processRefundViaGateway(payment: Payment, refund: Refund): Promise<boolean> {
  let success: boolean = false;
  let transactionId: string | null = null;
  // 'try/catch' for error handling with external gateway calls
  try {
    if (((payment.method === PaymentMethod.CreditCard) || (payment.method === PaymentMethod.DebitCard))) {
      let result: Record<string, any> = await stripeGateway.refund({transactionId: payment.transactionId, amount: (refund.amount * 100)});
      success = result['success'];
      transactionId = result['refundTransactionId'];
      if ((!success)) {
        refund.errorMessage = (result['error'] ?? 'Stripe refund failed');
      }
    } else if ((payment.method === PaymentMethod.PayPal)) {
      console.info('pay_pal_refund_skipped_configure_pay_pal_as_payment_provider_to_enable_gateway_refunds');
      refund.errorMessage = 'PayPal refunds require PayPal payment integration in integrations.dcfg';
      return false;
    } else if ((payment.method === PaymentMethod.BankTransfer)) {
      console.info('bank_transfer_refund_requires_manual_processing');
      refund.errorMessage = 'Bank transfer refunds require manual processing';
      return false;
    }
    if ((success && (transactionId != null))) {
      refund.refundTransactionId = transactionId;
    }
  }
  catch (e: any) {
    console.error('refund_processing_error');
    refund.errorMessage = `Gateway error: ${e.message}`;
    return false;
  }
  return success;
}

export function generateTransactionId(): string {
  return `TXN-${format(new Date(), 'yyyyMMddHHmmss')}-${Array.from({ length: 8 }, () => 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'.charAt(Math.floor(Math.random() * 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789'.length))).join('')}`;
}

/**
 * Standalone version of processPaymentAsync for use outside NestJS DI context
 * (e.g. queue workers). Accepts EntityManager as the last parameter.
 */
export async function processPaymentAsync(payment: Payment, cardToken: string | null, em: EntityManager): Promise<void> {
  payment.status = PaymentStatus.Processing;
  await em.getRepository(Payment).getEntityManager().persistAndFlush(payment);
  let success: boolean = false;
  let error: string | null = null;
  let gatewayResponse: string | null = null;
  try {
    if (((payment.method === PaymentMethod.CreditCard) || (payment.method === PaymentMethod.DebitCard))) {
      // External gateway integration call
      let result: Record<string, any> = await stripeGateway.charge({amount: (payment.amount * 100), currency: 'usd', source: cardToken, metadata: {transactionId: payment.transactionId, orderId: String(payment.orderId), customerId: String(payment.customerId)}});
      success = result['success'];
      gatewayResponse = JSON.stringify(result);
      if ((!success)) {
        error = (result['error'] ?? 'Stripe charge failed');
      }
    } else {
      if ((payment.method === PaymentMethod.PayPal)) {
        // PayPal gateway requires integrations.payment.provider: paypal in DCFG.
        // This example profile configures Stripe only; charges are not executed here.
        console.info('pay_pal_charge_skipped_configure_pay_pal_as_payment_provider_to_enable_gateway_charges');
        error = 'PayPal charges require PayPal payment integration in integrations.dcfg';
        success = false;
      } else {
        if ((payment.method === PaymentMethod.BankTransfer)) {
          payment.gatewayResponse = 'Bank transfer initiated - awaiting confirmation';
          await em.getRepository(Payment).getEntityManager().persistAndFlush(payment);
          return;
        } else {
          error = `Unsupported payment method: ${payment.method}`;
        }
      }
    }
  }
  catch (e: any) {
    success = false;
    error = `Payment gateway error: ${e.message}`;
    console.error('payment_processing_exception');
  }
  if (success) {
    payment.status = PaymentStatus.Completed;
    payment.processedAt = new Date();
    payment.gatewayResponse = gatewayResponse;
  } else {
    payment.status = PaymentStatus.Failed;
    payment.errorMessage = (error ?? 'Payment processing failed');
    payment.gatewayResponse = gatewayResponse;
  }
  await em.getRepository(Payment).getEntityManager().persistAndFlush(payment);
}

